INSERT IGNORE INTO knowledge_chunk (document_id, chunk_index, content, keywords, embedding_ref, created_at)
VALUES
(1, 0, 'English essays are evaluated by grammar accuracy, vocabulary range, structure, and logic. A strong essay uses examples as evidence and connects ideas with suitable transition words.', 'writing,essay,score', 'demo-keyword-index', CURRENT_TIMESTAMP),
(2, 0, 'Common English grammar errors include subject verb disagreement, wrong tense, missing articles, incorrect prepositions, and unclear pronoun reference.', 'grammar,error,writing', 'demo-keyword-index', CURRENT_TIMESTAMP),
(3, 0, 'LinguaMate uses a lightweight RAG knowledge base. RetrievalService searches knowledge_chunk by content and keywords, then AgentOrchestrator adds the retrieved snippets to the agent trace and injects them into the model prompt. The seed knowledge base includes writing rubrics, common grammar errors, RAG workflow notes, and tool descriptions.', 'rag,knowledge,retrieval,agent,知识库,检索', 'demo-keyword-index', CURRENT_TIMESTAMP),
(4, 0, 'LinguaMate tools include DictionaryTool for word lookup, NewsRecommendTool for reading recommendations, EssayScoringTool for writing review, RetrievalService for RAG knowledge search, and OpenAiCompatibleClient for model API calls. The agent loop is Observe, Think, Act, and Answer.', 'agent,tool,dictionary,news,writing,conversation,工具', 'demo-keyword-index', CURRENT_TIMESTAMP);
